\foreach \t in {-1,1,2,3,4} {\draw[color=black] (\t,-0.07)--(\t,0.07);\path (\t,-0.3) node[fill=white,inner sep=1pt,font=\fontsize{8.5}{10}\selectfont] {$\t$};}
