\foreach \t in {-1,1,2,3} {\draw[color=black] (-0.07,\t)--(0.07,\t);\path (-0.3,\t) node[fill=white,inner sep=1pt,font=\fontsize{8.5}{10}\selectfont] {$\t$};}
\foreach \a in {-1,0,1,2,3,4} {\foreach \b in {-1,0,1,2,3} {\pgfmathsetmacro{\m}{1-\a/2}\pgfmathsetmacro{\h}{0.22/sqrt(1+\m*\m)}\draw[color=black] ({\a-\h},{\b-\m*\h})--({\a+\h},{\b+\m*\h});}}
